            ),
            "66b199ec56f9d2cc8301cd43" to entry(
                "Supplication for wisdom, righteousness, and Paradise",
                "My Lord, grant me wisdom and join me with the righteous, grant me a truthful mention among later generations, and make me among the inheritors of the Garden of Bliss."
            ),
            "66b19a8856f9d2cc8301cd44" to entry(
                "Supplication for truth and divine support",
                "My Lord, admit me with a truthful entrance and bring me out with a truthful exit, and grant me from Yourself a supporting authority."
            ),
            "66b19b2656f9d2cc8301cd45" to entry(
                "Supplication for an open heart and ease in speech",
                "My Lord, expand for me my chest, ease for me my task, and untie a knot from my tongue so they may understand my speech."
            ),
            "66b19b7f56f9d2cc8301cd46" to entry(
                "Supplication for righteous spouse, offspring, and leadership",
