            ),
            "6756631df66804ebb0047b4c" to entry(
                "Supplication to remove anger",
                "I seek refuge in Allah from Satan, the accursed."
            ),
            "67566370f66804ebb0047b4d" to entry(
                "Supplication for safety",
                "O Allah, I ask You for well-being in this world and the Hereafter."
            ),
            "6756641df66804ebb0047b4e" to entry(
                "Supplication for forgiveness and not to be burdened beyond capacity",
                "Our Lord, do not impose blame upon us if we forget or make a mistake. Our Lord, do not burden us as You burdened those before us. Our Lord, do not burden us with what we cannot bear. Pardon us, forgive us, and have mercy on us. You are our Protector, so grant us victory over the disbelieving people."
            ),
            "67566545f66804ebb0047b4f" to entry(
                "Supplication for an open heart and ease in speech",
                "My Lord, expand for me my chest, ease for me my task, and untie a knot from my tongue so they may understand my speech."
            ),
            "675665cbf66804ebb0047b50" to entry(
                "Supplication to be kept from misguidance and granted mercy",
                "Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself. Indeed, You are the Bestower."
            ),
            "6756665af66804ebb0047b51" to entry(
                "Supplication when facing something distressing",
                "O Allah, I seek refuge in You from anxiety and grief, incapacity and laziness, cowardice and miserliness, the burden of debt and being overpowered by men."
            ),
            "675668aaf66804ebb0047b52" to entry(
                "Supplication for truth and divine support",
                "My Lord, admit me with a truthful entrance and bring me out with a truthful exit, and grant me from Yourself a supporting authority."
            ),
            "66b18cf056f9d2cc8301cd33" to entry(
                "Supplication when feeling pain",
                "In the name of Allah (3x). I seek refuge in Allah and His power from the evil of what I feel and fear (7x)."
            ),
            "66b18e0556f9d2cc8301cd34" to entry(
                "Supplication for protection from harm",
                "I seek refuge in the perfect words of Allah from His anger, His punishment, the evil of His servants, the whispers of devils, and their presence."
            ),
            "66b18e8e56f9d2cc8301cd35" to entry(
                "Supplication after taking medicine",
                "O Allah, heal me; You are the Healer. There is no healing except Your healing, a healing that leaves no illness."
            ),
            "66b18f4d56f9d2cc8301cd36" to entry(
                "Supplication for patience when ill",
                "Our Lord, pour upon us patience and let us die as Muslims."
            ),
            "66b1915356f9d2cc8301cd38" to entry(
                "Supplication when illness is severe",
                "I ask Allah the Mighty, Lord of the Mighty Throne, to cure you."
            ),
            "66b191a356f9d2cc8301cd39" to entry(
                "Supplication to remove anger",
                "I seek refuge in Allah from Satan, the accursed."
            ),
            "66b191fd56f9d2cc8301cd3a" to entry(
                "Supplication when facing something distressing",
                "O Allah, I seek refuge in You from anxiety and grief, incapacity and laziness, cowardice and miserliness, the burden of debt and being overpowered by men."
            ),
            "66b1928f56f9d2cc8301cd3b" to entry(
                "Supplication for safety",
                "O Allah, I ask You for well-being in this world and the Hereafter."
            ),
            "66b192de56f9d2cc8301cd3c" to entry(
                "Supplication for protection from epidemic",
                "I seek refuge in the perfect words of Allah from the evil of what He created."
            ),
            "68c8eac58ed36eba30085c43" to entry(
                "Supplication for complete healing",
                "O Allah, Lord of mankind, remove the harm and heal; You are the Healer. There is no healing except Your healing, a healing that leaves no illness."
            ),
            "fadhilah_001" to entry(
                "Supplication is the Most Noble Act Before Allah",
                "There is nothing more honorable in the sight of Allah Ta'ala than supplication."
            ),
            "fadhilah_002" to entry(
                "Condition for Answered Supplication: Certainty & Devotion",
                "Call upon Allah while you are certain of being answered, and know that Allah does not answer a supplication from a heedless, distracted heart."
            ),
            "fadhilah_003" to entry(
                "Three Forms of Answered Supplication for a Muslim",
                "There is no Muslim who supplicates to Allah with a prayer that does not involve sin or severing ties of kinship, except that Allah grants him one of three things: [1] Immediate fulfillment, [2] Stored reward in the Hereafter, or [3] Warding off an equivalent evil."
            ),
            "fadhilah_004" to entry(
                "Command to Supplicate & Warning Against Arrogance",
                "And your Lord says: 'Call upon Me; I will respond to you. Indeed, those who disdain My worship will enter Hell [rendered] contemptible.'"
            ),
            "quran_healing_ayyuub" to entry(
                "Prophet Ayyub's Prayer for Healing",
                "My Lord, indeed adversity has touched me, and You are the Most Merciful of the merciful."
            )
