            "sleep-dhikir:0" to "Dhikr Before Sleep",
            "dzikiralmathuratkubro:0" to "Al-Mathurat Kubra",
            "dzikiralmathuratsughro:0" to "Al-Mathurat Sughra"
        ),
        dhikrContent = mapOf(
            // Morning Dhikr
            "morning-dhikir:0:0" to entry(translation = "Allah! There is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great."),
            "morning-dhikir:0:1" to entry(translation = "Reciting Surah Al-Ikhlas, Al-Falaq, and An-Naas."),
            "morning-dhikir:0:2" to entry(translation = "We have entered the morning and the kingdom belongs to Allah, and all praise is for Allah. There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things. My Lord, I ask You for the good of this day and the good of what comes after it, and I seek refuge in You from the evil of this day and the evil of what comes after it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave."),
            "morning-dhikir:0:3" to entry(translation = "O Allah, by You we enter the morning, and by You we enter the evening, and by You we live, and by You we die, and to You is the resurrection."),
            "morning-dhikir:0:4" to entry(translation = "O Allah, You are my Lord. There is no deity except You. You created me and I am Your servant. I uphold Your covenant and promise as best I can. I seek refuge in You from the evil I have done. I acknowledge Your favor upon me and confess my sin, so forgive me, for none forgives sins except You."),
            "morning-dhikir:0:5" to entry(translation = "O Allah, I have entered the morning and I call upon You, the bearers of Your Throne, Your angels, and all of Your creation to witness that You are Allah, there is no deity except You alone, without partner, and that Muhammad is Your servant and Messenger."),
            "morning-dhikir:0:6" to entry(translation = "O Allah, I ask You for pardon and well-being in this world and the Hereafter. O Allah, I ask You for pardon and well-being in my religion, my worldly affairs, my family, and my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and from behind me, from my right and from my left, and from above me; and I seek refuge in Your greatness from being swallowed up from beneath me."),
            "morning-dhikir:0:7" to entry(translation = "O Allah, Knower of the unseen and the witnessed, Creator of the heavens and the earth, Lord and Sovereign of all things. I bear witness that there is no deity except You. I seek refuge in You from the evil of myself, and from the evil of Satan and his shirk, and that I commit any evil against myself or bring it upon another Muslim."),
            "morning-dhikir:0:8" to entry(translation = "In the name of Allah, with whose name nothing in the earth or in the heaven can cause harm, and He is the All-Hearing, the All-Knowing."),
            "morning-dhikir:0:9" to entry(translation = "I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace and blessings of Allah be upon him) as my Prophet."),
            "morning-dhikir:0:10" to entry(translation = "O Ever-Living, O Self-Sustaining Peerless One, by Your mercy I seek helper, rectify for me all of my affairs and do not leave me to myself even for the blink of an eye."),
            "morning-dhikir:0:11" to entry(translation = "We have entered the morning upon the natural religion of Islam, the word of sincere devotion, the religion of our Prophet Muhammad (peace and blessings of Allah be upon him), and the creed of our father Ibrahim, a monotheist and a Muslim, and he was not of those who associate partners with Allah."),
            "morning-dhikir:0:12" to entry(translation = "Glory be to Allah and His is the praise."),
            "morning-dhikir:0:13" to entry(translation = "There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things."),
            "morning-dhikir:0:14" to entry(translation = "There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things."),
            "morning-dhikir:0:15" to entry(translation = "Glory be to Allah and His is the praise, by the number of His creation, His pleasure, the weight of His Throne, and the ink of His words."),
            "morning-dhikir:0:16" to entry(translation = "O Allah, I ask You for beneficial knowledge, wholesome sustenance, and acceptable deeds."),
            "morning-dhikir:0:17" to entry(translation = "I seek the forgiveness of Allah and turn to Him in repentance."),

            // Evening Dhikr
            "evening-dhikir:0:0" to entry(translation = "Allah! There is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great."),
            "evening-dhikir:0:1" to entry(translation = "Reciting Surah Al-Ikhlas, Al-Falaq, and An-Naas."),
            "evening-dhikir:0:2" to entry(translation = "We have entered the evening and the kingdom belongs to Allah, and all praise is for Allah. There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things. My Lord, I ask You for the good of this night and the good of what comes after it, and I seek refuge in You from the evil of this night and the evil of what comes after it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave."),
            "evening-dhikir:0:3" to entry(translation = "O Allah, by You we enter the evening, and by You we enter the morning, and by You we live, and by You we die, and to You is the final return."),
            "evening-dhikir:0:4" to entry(translation = "O Allah, You are my Lord. There is no deity except You. You created me and I am Your servant. I uphold Your covenant and promise as best I can. I seek refuge in You from the evil I have done. I acknowledge Your favor upon me and confess my sin, so forgive me, for none forgives sins except You."),
            "evening-dhikir:0:5" to entry(translation = "O Allah, I have entered the evening and I call upon You, the bearers of Your Throne, Your angels, and all of Your creation to witness that You are Allah, there is no deity except You alone, without partner, and that Muhammad is Your servant and Messenger."),
            "evening-dhikir:0:6" to entry(translation = "O Allah, I ask You for pardon and well-being in this world and the Hereafter. O Allah, I ask You for pardon and well-being in my religion, my worldly affairs, my family, and my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and from behind me, from my right and from my left, and from above me; and I seek refuge in Your greatness from being swallowed up from beneath me."),
            "evening-dhikir:0:7" to entry(translation = "O Allah, Knower of the unseen and the witnessed, Creator of the heavens and the earth, Lord and Sovereign of all things. I bear witness that there is no deity except You. I seek refuge in You from the evil of myself, and from the evil of Satan and his shirk, and that I commit any evil against myself or bring it upon another Muslim."),
            "evening-dhikir:0:8" to entry(translation = "In the name of Allah, with whose name nothing in the earth or in the heaven can cause harm, and He is the All-Hearing, the All-Knowing."),
            "evening-dhikir:0:9" to entry(translation = "I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace and blessings of Allah be upon him) as my Prophet."),
            "evening-dhikir:0:10" to entry(translation = "O Ever-Living, O Self-Sustaining Peerless One, by Your mercy I seek helper, rectify for me all of my affairs and do not leave me to myself even for the blink of an eye."),
            "evening-dhikir:0:11" to entry(translation = "Glory be to Allah and His is the praise."),
            "evening-dhikir:0:12" to entry(translation = "There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things."),
            "evening-dhikir:0:13" to entry(translation = "I seek refuge in the perfect words of Allah from the evil of what He has created."),

            // Sleep Dhikr
            "sleep-dhikir:0:0" to entry(translation = "Reciting Surah Al-Ikhlas, Al-Falaq, and An-Naas, blowing into hands, and wiping over the body."),
            "sleep-dhikir:0:1" to entry(translation = "Reciting Ayat Kursi."),
            "sleep-dhikir:0:2" to entry(translation = "The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers..."),
            "sleep-dhikir:0:3" to entry(translation = "In Your name, my Lord, I lay down my side, and by You I raise it. If You take my soul, then have mercy upon it, and if You release it, then guard it as You guard Your righteous servants."),
            "sleep-dhikir:0:4" to entry(translation = "O Allah, You created my soul and You take it. To You belongs its life and its death. If You keep it alive, then guard it, and if You cause it to die, then forgive it. O Allah, I ask You for well-being."),
            "sleep-dhikir:0:5" to entry(translation = "O Allah, protect me from Your punishment on the Day You resurrect Your servants."),
            "sleep-dhikir:0:6" to entry(translation = "In Your name, O Allah, I die and I live."),
            "sleep-dhikir:0:7" to entry(translation = "Glory be to Allah (33 times), Praise be to Allah (33 times), Allah is the Greatest (34 times)."),
            "sleep-dhikir:0:8" to entry(translation = "O Allah, Lord of the seven heavens and Lord of the Magnificent Throne, our Lord and Lord of all things. Lord of the grain and the seed, and Revealer of the Torah, the Gospel, and the Furqan. I seek refuge in You from the evil of everything You hold by its forelock. O Allah, You are the First, before whom there is nothing; You are the Last, after whom there is nothing; You are the Manifest, above whom there is nothing; and You are the Hidden, beneath whom there is nothing. Settle our debts and enrich us from poverty."),
            "sleep-dhikir:0:9" to entry(translation = "Praise be to Allah who fed us, gave us drink, sufficed us, and gave us shelter, for how many are there who have no one to suffice them and no shelter."),
            "sleep-dhikir:0:10" to entry(translation = "O Allah, Knower of the unseen and the witnessed, Creator of the heavens and the earth, Lord and Sovereign of all things. I bear witness that there is no deity except You. I seek refuge in You from the evil of myself, and from the evil of Satan and his shirk, and that I commit any evil against myself or bring it upon another Muslim."),
            "sleep-dhikir:0:11" to entry(translation = "Reciting Surah As-Sajdah and Surah Al-Mulk."),
            "sleep-dhikir:0:12" to entry(translation = "O Allah, I submit myself to You, and I entrust my affairs to You, and I turn my face to You, and I lay myself down relying on You, out of hope and fear of You. There is no refuge and no salvation from You except in You. I believe in the Book You have revealed, and in the Prophet You have sent."),

            // Dhikr After Salah
            "dhikir-after-salah:0:0" to entry(translation = "I seek the forgiveness of Allah (3 times)."),
            "dhikir-after-salah:0:1" to entry(translation = "O Allah, You are Peace and from You comes peace. Blessed are You, O Possessor of majesty and honor."),
            "dhikir-after-salah:0:2" to entry(translation = "There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things. O Allah, none can prevent what You give, and none can give what You prevent, and no wealth or majesty can benefit its possessor against You."),
            "dhikir-after-salah:0:3" to entry(translation = "There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things. There is no power and no strength except by Allah. There is no deity except Allah, and we worship none but Him. To Him belongs all favor, grace, and good praise. There is no deity except Allah, making our worship sincere to Him even if the disbelievers dislike it."),
            "dhikir-after-salah:0:4" to entry(translation = "Glory be to Allah (33 times)."),
            "dhikir-after-salah:0:5" to entry(translation = "Praise be to Allah (33 times)."),
            "dhikir-after-salah:0:6" to entry(translation = "Allah is the Greatest (33 times)."),
            "dhikir-after-salah:0:7" to entry(translation = "There is no deity except Allah alone, without partner. To Him belongs dominion and praise, and He is competent over all things."),
            "dhikir-after-salah:0:8" to entry(translation = "Allah! There is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth..."),
            "dhikir-after-salah:0:9" to entry(translation = "Reciting Surah Al-Ikhlas, Al-Falaq, and An-Naas."),
            "dhikir-after-salah:0:10" to entry(translation = "O Allah, I ask You for beneficial knowledge, wholesome sustenance, and acceptable deeds.")
        )
    )

    val malay: DoaLocaleData by lazy {
        DoaLocaleData(
            categories = mapOf(
                "daily" to "Doa Harian",
                "selected" to "Doa Pilihan",
                "doa-ketika-sakit" to "Doa Ketika Sakit",
                "morning-dhikir" to "Zikir Pagi",
                "evening-dhikir" to "Zikir Petang",
                "dhikir-after-salah" to "Zikir Selepas Solat",
                "sleep-dhikir" to "Zikir Sebelum Tidur",
                "fadhilahdoa" to "Fadhilah Doa",
                "dzikiralmathuratkubro" to "Dzikir Al-Mathurat Kubro",
                "dzikiralmathuratsughro" to "Dzikir Al-Mathurat Sugro"
            ),
            doa = english.doa.mapNotNull { (key, value) ->
                val m = malayDoa[value.title]
                if (m != null) key to m else null
            }.toMap(),
            dhikrTitles = mapOf(
                "morning-dhikir:0" to "Zikir Pagi",
                "evening-dhikir:0" to "Zikir Petang",
                "dhikir-after-salah:0" to "Zikir Selepas Solat Fardu",
                "sleep-dhikir:0" to "Zikir Sebelum Tidur",
                "dzikiralmathuratkubro:0" to "Dzikir Al-Mathurat Kubro",
                "dzikiralmathuratsughro:0" to "Dzikir Al-Mathurat Sugro"
            ),
            dhikrContent = mapOf(
                // Morning Dhikr
                "morning-dhikir:0:0" to entry(translation = "Allah, tiada Tuhan melainkan Dia, Yang Hidup Kekal lagi terus menerus mengurus (makhluk-Nya). Dia tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafaat di sisi-Nya tanpa izin-Nya. Dia mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka, dan mereka tidak mengetahui sesuatu pun dari ilmu-Nya melainkan apa yang Dia kehendaki. Kursi-Nya meliputi langit dan bumi, dan pemeliharaan kedua-duanya tidak melelahkan-Nya. Dan Dia Maha Tinggi lagi Maha Agung."),
                "morning-dhikir:0:1" to entry(translation = "Membaca Surah Al-Ikhlas, Al-Falaq, dan An-Naas."),
                "morning-dhikir:0:2" to entry(translation = "Kami telah memasuki waktu pagi dan kerajaan hanya milik Allah, segala puji bagi Allah. Tidak ada tuhan melainkan Allah Yang Maha Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan bagi-Nya pujian. Wahai Tuhanku, aku memohon kepada-Mu kebaikan hari ini dan kebaikan selepasnya, dan aku berlindung kepada-Mu dari keburukan hari ini dan keburukan selepasnya. Wahai Tuhanku, aku berlindung kepada-Mu dari kemalasan dan keburukan usia tua. Wahai Tuhanku, aku berlindung kepada-Mu dari azab neraka dan azab kubur."),
                "morning-dhikir:0:3" to entry(translation = "Ya Allah, dengan rahmat dan pertolongan-Mu kami memasuki waktu pagi, dan dengan rahmat dan pertolongan-Mu kami memasuki waktu petang. Dengan rahmat dan pertolongan-Mu kami hidup dan dengan kehendak-Mu kami mati. Dan kepada-Mu kebangkitan."),
                "morning-dhikir:0:4" to entry(translation = "Ya Allah, Engkaulah Tuhanku, tiada tuhan selain Engkau. Engkau menciptakanku dan aku adalah hamba-Mu. Aku menunaikan janji kepada-Mu sekuat kemampuanku. Aku berlindung kepada-Mu dari kejahatan yang aku lakukan. Aku mengakui nikmat-Mu dan mengaku dosaku, maka ampunilah aku, kerana tiada yang mengampuni dosa melainkan Engkau."),
                "morning-dhikir:0:5" to entry(translation = "Ya Allah, sesungguhnya aku di waktu pagi ini mempersaksikan Engkau, malaikat yang memikul ‘Arsy-Mu, malaikat-malaikat dan seluruh makhluk-Mu, bahawa sesungguhnya Engkau adalah Allah, tiada tuhan melainkan Engkau Yang Maha Esa tiada sekutu bagi-Mu, dan bahawa Muhammad adalah hamba dan utusan-Mu."),
                "morning-dhikir:0:6" to entry(translation = "Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan di dunia dan akhirat. Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan dalam agama, dunia, keluarga dan hartaku. Ya Allah, tutuplah aibku dan tenteramkanlah kebimbanganku. Ya Allah, peliharalah aku dari hadapan, belakang, kanan, kiri dan atasku. Aku berlindung dengan keagungan-Mu agar tidak dibinasakan dari bawahku."),
                "morning-dhikir:0:7" to entry(translation = "Ya Allah, Yang Maha Mengetahui yang ghaib dan nyata, pencipta langit dan bumi, Tuhan segala sesuatu dan rajanya. Aku bersaksi bahawa tiada tuhan yang berhak disembah kecuali Engkau. Aku berlindung kepada-Mu dari kejahatan diriku, kejahatan syaitan dan sekutunya, serta daripada aku melakukan keburukan ke atas diriku atau membawanya kepada seorang Muslim."),
                "morning-dhikir:0:8" to entry(translation = "Dengan nama Allah yang bila disebut, segala sesuatu di bumi dan langit tidak akan berbahaya, Dia-lah Yang Maha Mendengar lagi Maha Mengetahui."),
                "morning-dhikir:0:9" to entry(translation = "Aku redha Allah sebagai Rabb, Islam sebagai agama dan Muhammad shallallahu 'alaihi wa sallam sebagai nabi."),
                "morning-dhikir:0:10" to entry(translation = "Wahai Rabb Yang Maha Hidup, wahai Rabb Yang Berdiri Sendiri, dengan rahmat-Mu aku memohon pertolongan, perbaikilah segala urusanku dan janganlah Engkau serahkan kepadaku sekali pun sekejap mata."),
                "morning-dhikir:0:11" to entry(translation = "Di waktu pagi kami memegang agama Islam, kalimat ikhlas (kalimat syahadat), agama Nabi kami Muhammad shallallahu ‘alaihi wa sallam, dan agama bapak kami Ibrahim yang hanif lagi berserah diri, dan dia bukanlah dari kalangan orang-orang musyrik."),
                "morning-dhikir:0:12" to entry(translation = "Maha suci Allah, aku memuji-Nya."),
                "morning-dhikir:0:13" to entry(translation = "Tidak ada tuhan yang berhak disembah selain Allah semata, tidak ada sekutu bagi-Nya. Bagi-Nya kerajaan dan segala pujian. Dia-lah yang berkuasa atas segala sesuatu."),
                "morning-dhikir:0:14" to entry(translation = "Tidak ada tuhan yang berhak disembah selain Allah semata, tidak ada sekutu bagi-Nya. Bagi-Nya kerajaan dan segala pujian. Dia-lah yang berkuasa atas segala sesuatu."),
                "morning-dhikir:0:15" to entry(translation = "Maha Suci Allah, aku memujiNya sebanyak bilangan makhluk-Nya, keredhaan diri-Nya, seberat timbangan ‘Arsy-Nya dan sebanyak tinta tulisan kalimat-Nya."),
                "morning-dhikir:0:16" to entry(translation = "Ya Allah, sungguh aku memohon kepada-Mu ilmu yang bermanfaat, rezeki yang halal dan amal yang diterima."),
                "morning-dhikir:0:17" to entry(translation = "Aku memohon ampun kepada Allah dan bertaubat kepada-Nya."),

                // Evening Dhikr
                "evening-dhikir:0:0" to entry(translation = "Allah, tiada Tuhan melainkan Dia, Yang Hidup Kekal lagi terus menerus mengurus (makhluk-Nya). Dia tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafaat di sisi-Nya tanpa izin-Nya. Dia mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka, dan mereka tidak mengetahui sesuatu pun dari ilmu-Nya melainkan apa yang Dia kehendaki. Kursi-Nya meliputi langit dan bumi, dan pemeliharaan kedua-duanya tidak melelahkan-Nya. Dan Dia Maha Tinggi lagi Maha Agung."),
                "evening-dhikir:0:1" to entry(translation = "Membaca Surah Al-Ikhlas, Al-Falaq, dan An-Naas."),
                "evening-dhikir:0:2" to entry(translation = "Kami telah memasuki waktu petang dan kerajaan hanya milik Allah, segala puji bagi Allah. Tidak ada tuhan melainkan Allah Yang Maha Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan bagi-Nya pujian. Wahai Tuhanku, aku memohon kepada-Mu kebaikan malam ini dan kebaikan selepasnya, dan aku berlindung kepada-Mu dari keburukan malam ini dan keburukan selepasnya. Wahai Tuhanku, aku berlindung kepada-Mu dari kemalasan dan keburukan usia tua. Wahai Tuhanku, aku berlindung kepada-Mu dari azab neraka dan azab kubur."),
                "evening-dhikir:0:3" to entry(translation = "Ya Allah, dengan rahmat dan pertolongan-Mu kami memasuki waktu petang, dan dengan rahmat dan pertolongan-Mu kami memasuki waktu pagi. Dengan rahmat dan pertolongan-Mu kami hidup dan dengan kehendak-Mu kami mati. Dan kepada-Mu tempat kembali."),
                "evening-dhikir:0:4" to entry(translation = "Ya Allah, Engkaulah Tuhanku, tiada tuhan selain Engkau. Engkau menciptakanku dan aku adalah hamba-Mu. Aku menunaikan janji kepada-Mu sekuat kemampuanku. Aku berlindung kepada-Mu dari kejahatan yang aku lakukan. Aku mengakui nikmat-Mu dan mengaku dosaku, maka ampunilah aku, kerana tiada yang mengampuni dosa melainkan Engkau."),
                "evening-dhikir:0:5" to entry(translation = "Ya Allah, sesungguhnya aku di waktu petang ini mempersaksikan Engkau, malaikat yang memikul ‘Arsy-Mu, malaikat-malaikat dan seluruh makhluk-Mu, bahawa sesungguhnya Engkau adalah Allah, tiada tuhan melainkan Engkau Yang Maha Esa tiada sekutu bagi-Mu, dan bahawa Muhammad adalah hamba dan utusan-Mu."),
                "evening-dhikir:0:6" to entry(translation = "Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan di dunia dan akhirat. Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan dalam agama, dunia, keluarga dan hartaku. Ya Allah, tutuplah aibku dan tenteramkanlah kebimbanganku. Ya Allah, peliharalah aku dari hadapan, belakang, kanan, kiri dan atasku. Aku berlindung dengan keagungan-Mu agar tidak dibinasakan dari bawahku."),
                "evening-dhikir:0:7" to entry(translation = "Ya Allah, Yang Maha Mengetahui yang ghaib dan nyata, pencipta langit dan bumi, Tuhan segala sesuatu dan rajanya. Aku bersaksi bahawa tiada tuhan yang berhak disembah kecuali Engkau. Aku berlindung kepada-Mu dari kejahatan diriku, kejahatan syaitan dan sekutunya, serta daripada aku melakukan keburukan ke atas diriku atau membawanya kepada seorang Muslim."),
                "evening-dhikir:0:8" to entry(translation = "Dengan nama Allah yang bila disebut, segala sesuatu di bumi dan langit tidak akan berbahaya, Dia-lah Yang Maha Mendengar lagi Maha Mengetahui."),
                "evening-dhikir:0:9" to entry(translation = "Aku redha Allah sebagai Rabb, Islam sebagai agama dan Muhammad shallallahu 'alaihi wa sallam sebagai nabi."),
                "evening-dhikir:0:10" to entry(translation = "Wahai Rabb Yang Maha Hidup, wahai Rabb Yang Berdiri Sendiri, dengan rahmat-Mu aku memohon pertolongan, perbaikilah segala urusanku dan janganlah Engkau serahkan kepadaku sekali pun sekejap mata."),
                "evening-dhikir:0:11" to entry(translation = "Maha suci Allah, aku memuji-Nya."),
                "evening-dhikir:0:12" to entry(translation = "Tidak ada tuhan yang berhak disembah selain Allah semata, tidak ada sekutu bagi-Nya. Bagi-Nya kerajaan dan segala pujian. Dia-lah yang berkuasa atas segala sesuatu."),
                "evening-dhikir:0:13" to entry(translation = "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari kejahatan makhluk yang diciptakan-Nya."),

                // Sleep Dhikr
                "sleep-dhikir:0:0" to entry(translation = "Mengumpulkan kedua telapak tangan. Ditiup dan dibacakan Surah Al-Ikhlas, Al-Falaq dan An-Naas. Kemudian menyapu kedua telapak tangan ke seluruh tubuh yang dapat dijangkau, dimulai dari kepala, wajah dan tubuh bahagian hadapan."),
                "sleep-dhikir:0:1" to entry(translation = "Membaca Ayat Kursi."),
                "sleep-dhikir:0:2" to entry(translation = "Rasul telah beriman kepada Al-Qur’an yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman..."),
                "sleep-dhikir:0:3" to entry(translation = "Dengan nama-Mu, wahai Rabbku, aku meletakkan lambungku. Dan dengan nama-Mu pula aku bangun. Jika Engkau menahan rohku (mati), maka rahmatilah ia. Dan jika Engkau melepaskannya, maka peliharalah ia sebagaimana Engkau memelihara hamba-hamba-Mu yang soleh."),
                "sleep-dhikir:0:4" to entry(translation = "Ya Allah, sesungguhnya Engkau menciptakan diriku, dan Engkaulah yang mematikannya. Mati dan hidupnya hanya milik-Mu. Jika Engkau menghidupkannya, peliharalah ia. Jika Engkau mematikannya, ampunilah ia. Ya Allah, sesungguhnya aku memohon kepada-Mu keselamatan."),
                "sleep-dhikir:0:5" to entry(translation = "Ya Allah, peliharalah aku dari azab-Mu pada hari Engkau membangkitkan hamba-hamba-Mu."),
                "sleep-dhikir:0:6" to entry(translation = "Dengan nama-Mu, ya Allah, aku mati dan hidup."),
                "sleep-dhikir:0:7" to entry(translation = "Maha suci Allah (33x), segala puji bagi Allah (33x), Allah Maha Besar (34x)."),
                "sleep-dhikir:0:8" to entry(translation = "Ya Allah, Tuhan yang menguasai langit yang tujuh, Tuhan yang menguasai ‘Arsy yang agung, Tuhan kami dan Tuhan segala sesuatu. Tuhan yang membelah bijian dan benih, Tuhan yang menurunkan Taurat, Injil dan Al-Furqan. Aku berlindung kepada-Mu dari kejahatan setiap sesuatu yang Engkau pegang ubun-ubunnya. Ya Allah, Engkaulah yang awal, tiada sesuatu sebelum-Mu; Engkaulah yang akhir, tiada sesuatu selepas-Mu; Engkaulah yang nyata, tiada sesuatu di atas-Mu; Engkaulah yang batin, tiada sesuatu di bawah-Mu. Lunaskanlah hutang kami dan cukupkanlah kami daripada kefakiran."),
                "sleep-dhikir:0:9" to entry(translation = "Segala puji bagi Allah yang memberi makan kami, memberi minum kami, mencukupi kami, dan memberi tempat berteduh. Berapa banyak orang yang tidak mempunyai sesiapa yang mencukupi dan memberi tempat berteduh."),
                "sleep-dhikir:0:10" to entry(translation = "Ya Allah, Yang Maha Mengetahui yang ghaib dan nyata, pencipta langit dan bumi, Tuhan segala sesuatu dan rajanya. Aku bersaksi bahawa tiada tuhan yang berhak disembah kecuali Engkau. Aku berlindung kepada-Mu dari kejahatan diriku, kejahatan syaitan dan sekutunya, serta daripada aku melakukan keburukan ke atas diriku atau membawanya kepada seorang Muslim."),
                "sleep-dhikir:0:11" to entry(translation = "Membaca Surah As-Sajdah dan Surah Al-Mulk."),
                "sleep-dhikir:0:12" to entry(translation = "Ya Allah, aku menyerahkan diriku kepada-Mu, aku menyerahkan urusanku kepada-Mu, aku menghadapkan wajahku kepada-Mu, aku menyandarkan punggungku kepada-Mu, kerana mengharap rahmat-Mu dan takut akan azab-Mu. Tiada tempat perlindungan dan keselamatan daripada-Mu melainkan kepada-Mu. Aku beriman kepada kitab-Mu yang telah Engkau turunkan dan Nabi-Mu yang telah Engkau utus."),

                // Dhikr After Salah
                "dhikir-after-salah:0:0" to entry(translation = "Aku memohon ampun kepada Allah (3x)."),
                "dhikir-after-salah:0:1" to entry(translation = "Ya Allah, Engkau pemberi keselamatan, dan dari-Mu keselamatan. Maha Berkat Engkau, wahai Pemilik Keagungan dan Kemuliaan."),
                "dhikir-after-salah:0:2" to entry(translation = "Tiada Tuhan yang berhak disembah selain Allah Yang Maha Esa, tiada sekutu bagi-Nya. Bagi-Nya puji dan bagi-Nya kerajaan. Dia Maha Kuasa atas segala sesuatu. Ya Allah, tidak ada yang mencegah apa yang Engkau berikan, dan tidak ada yang memberi apa yang Engkau cegah, dan tidak ada kekayaan mahupun kedudukan yang dapat memberi manfaat kepada pemiliknya daripada azab-Mu."),
                "dhikir-after-salah:0:3" to entry(translation = "Tiada Tuhan yang berhak disembah selain Allah Yang Maha Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan pujian. Dia Maha Kuasa atas segala sesuatu. Tiada daya dan kekuatan melainkan dengan pertolongan Allah. Tiada Tuhan melainkan Allah, dan kami tidak menyembah melainkan Dia. Bagi-Nya segala nikmat, limpah kurnia, dan pujian yang baik. Tiada Tuhan melainkan Allah, dengan mengikhlaskan ibadah kepada-Nya walaupun orang-orang kafir membencinya."),
                "dhikir-after-salah:0:4" to entry(translation = "Maha Suci Allah (33x)."),
                "dhikir-after-salah:0:5" to entry(translation = "Segala puji bagi Allah (33x)."),
                "dhikir-after-salah:0:6" to entry(translation = "Allah Maha Besar (33x)."),
                "dhikir-after-salah:0:7" to entry(translation = "Tiada Tuhan melainkan Allah Yang Maha Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan pujian, dan Dia Maha Kuasa atas segala sesuatu."),
                "dhikir-after-salah:0:8" to entry(translation = "Membaca Ayat Kursi selesai solat fardhu."),
                "dhikir-after-salah:0:9" to entry(translation = "Membaca Surah Al-Ikhlas, Al-Falaq, dan An-Naas selesai solat fardhu."),
                "dhikir-after-salah:0:10" to entry(translation = "Ya Allah, sungguh aku memohon kepada-Mu ilmu yang bermanfaat, rezeki yang halal dan amal yang diterima.")
            )
        )
    }

    private fun entry(title: String? = null, translation: String? = null, notes: String? = null) =
        DoaLocaleEntry(title = title, translation = translation, notes = notes)

    private val malayDoa = mapOf(
        "Supplication for good in this world and the Hereafter" to entry(
            "Doa memohon kebaikan dunia dan akhirat",
            "Wahai Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari azab neraka."
        ),
        "Supplication for mercy and guidance" to entry(
            "Doa memohon rahmat dan petunjuk",
            "Wahai Tuhan kami, kurniakanlah kepada kami rahmat dari sisi-Mu dan mudahkanlah bagi kami urusan kami dengan petunjuk yang benar."
        ),
        "Supplication to be kept from misguidance and granted mercy" to entry(
            "Doa dijauhi kesesatan dan dikurniakan rahmat",
            "Wahai Tuhan kami, janganlah Engkau pesongkan hati kami setelah Engkau beri petunjuk, dan kurniakanlah kepada kami rahmat dari sisi-Mu. Sesungguhnya Engkau Maha Pengurnia."
        ),
        "Supplication for forgiveness for oneself and believing brethren" to entry(
            "Doa ampunan untuk diri dan saudara seiman",
            "Wahai Tuhan kami, ampunilah kami dan saudara-saudara kami yang telah beriman lebih dahulu daripada kami, dan janganlah Engkau letakkan dalam hati kami dendam terhadap orang yang beriman. Wahai Tuhan kami, sesungguhnya Engkau Maha Pengasih lagi Maha Penyayang."
        ),
        "Supplication for forgiveness and protection from Hellfire" to entry(
            "Doa ampunan dan pelindungan dari neraka",
            "Wahai Tuhan kami, kami telah beriman, maka ampunilah dosa-dosa kami dan peliharalah kami dari azab neraka."
        ),
        "Supplication for pardon and not to be burdened beyond capacity" to entry(
            "Doa ampunan dan tidak dibebankan melampaui kemampuan",
            "Wahai Tuhan kami, janganlah Engkau tuduh kami jika kami lupa atau tersalah. Wahai Tuhan kami, janganlah Engkau bebankan kepada kami beban seperti yang Engkau bebankan kepada orang sebelum kami. Wahai Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tidak sanggup kami pikul. Maafkan kami, ampunilah kami, dan rahmatilah kami. Engkaulah Pelindung kami, maka tolonglah kami menghadapi kaum yang kafir."
        ),
        "Supplication for wisdom, righteousness, and Paradise" to entry(
            "Doa memohon hikmah, kebaikan, dan syurga",
            "Wahai Tuhanku, kurniakanlah kepadaku hikmah dan sertakanlah aku dengan orang-orang yang soleh, jadikanlah aku sebagai sebutan yang benar di kalangan generasi kemudian, dan jadikanlah aku termasuk pewaris syurga yang penuh kenikmatan."
        ),
        "Supplication for truth and divine support" to entry(
            "Doa memohon kebenaran dan pertolongan",
            "Wahai Tuhanku, masukkanlah aku dengan cara yang benar dan keluarkanlah aku dengan cara yang benar, serta kurniakanlah kepadaku dari sisi-Mu kekuasaan yang menolong."
        ),
        "Supplication for an open heart and ease in speech" to entry(
            "Doa memohon lapang hati dan lancar pertuturan",
            "Wahai Tuhanku, lapangkanlah dadaku, mudahkanlah urusanku, dan lepaskanlah kekakuan lidahku agar mereka memahami ucapanku."
        ),
        "Supplication for righteous spouse, offspring, and leadership" to entry(
            "Doa memohon pasangan, zuriat, dan kepimpinan",
            "Wahai Tuhan kami, kurniakanlah kepada kami pasangan dan zuriat sebagai penyejuk mata, dan jadikanlah kami pemimpin bagi orang-orang yang bertakwa."
        ),
        "Supplication for accepted deeds" to entry(
            "Doa memohon amalan diterima",
            "Wahai Tuhan kami, terimalah daripada kami. Sesungguhnya Engkau Maha Mendengar lagi Maha Mengetahui."
        ),
        "Supplication for protection from human and other harm" to entry(
            "Doa terlindung dari kejahatan manusia dan makhluk lain",
            "Aku berlindung dengan kalimah-kalimah Allah yang sempurna dari kemurkaan-Nya, azab-Nya, kejahatan hamba-hamba-Nya, bisikan syaitan, dan kehadiran mereka."
        ),
        "Supplication to remove anger" to entry(
            "Doa menghilangkan kemarahan",
            "Aku berlindung kepada Allah daripada syaitan yang dirempuh."
        ),
        "Supplication for safety" to entry(
            "Doa keselamatan",
            "Ya Allah, aku memohon kepada-Mu keselamatan di dunia dan akhirat."
        ),
        "Supplication when facing something distressing" to entry(
            "Doa menghadapi hal yang membimbangkan",
            "Ya Allah, aku berlindung kepada-Mu dari kebimbangan dan kesedihan, kelemahan dan kemalasan, kepengecutan dan kekikiran, beban hutang dan dikuasai oleh manusia."
        ),
        "Supplication after taking medicine" to entry(
            "Doa selepas minum ubat",
            "Ya Allah, sembuhkanlah aku; Engkaulah Yang Menyembuhkan. Tiada penyembuhan melainkan penyembuhan-Mu, penyembuhan yang tidak meninggalkan penyakit."
        ),
        "Supplication for patience when ill" to entry(
            "Doa memohon kesabaran ketika sakit",
            "Wahai Tuhan kami, curahkanlah kesabaran ke atas kami dan matikanlah kami dalam keadaan Islam."
        ),
        "Supplication when illness is severe" to entry(
            "Doa ketika penyakit teruk",
            "Aku memohon kepada Allah Yang Maha Perkasa, Tuhan Arasy yang agung, agar menyembuhkanmu."
        ),
        "Supplication when feeling pain" to entry(
            "Doa ketika merasakan sakit",
            "Dengan nama Allah (3x). Aku berlindung kepada Allah dan kekuasaan-Nya dari kejahatan yang aku rasakan dan khawatirkan (7x)."
        ),
        "Supplication for protection from harm" to entry(
            "Doa terlindung dari kejahatan",
            "Aku berlindung dengan kalimah-kalimah Allah yang sempurna dari kemurkaan-Nya, azab-Nya, kejahatan hamba-hamba-Nya, bisikan syaitan, dan kehadiran mereka."
        ),
        "Supplication for protection from epidemic" to entry(
            "Doa terlindung dari wabak penyakit",
            "Aku berlindung dengan kalimah-kalimah Allah yang sempurna dari kejahatan apa yang Dia ciptakan."
        ),
        "Supplication for complete healing" to entry(
            "Doa memohon kesembuhan sempurna",
            "Ya Allah, Tuhan manusia, hilangkanlah penyakit dan sembuhkanlah; Engkaulah Yang Menyembuhkan. Tiada penyembuhan melainkan penyembuhan-Mu, penyembuhan yang tidak meninggalkan penyakit."
        )
    )
}

internal data class DoaLocaleData(
    val categories: Map<String, String> = emptyMap(),
    val doa: Map<String, DoaLocaleEntry> = emptyMap(),
    val dhikrTitles: Map<String, String> = emptyMap(),
    val dhikrContent: Map<String, DoaLocaleEntry> = emptyMap()
)

internal data class DoaLocaleEntry(
    val title: String? = null,
    val translation: String? = null,
    val notes: String? = null
)
